abstract class GenerateSnippets : DefaultTask() {
    @get:InputDirectory
    abstract val sourceDir: DirectoryProperty

    @get:OutputDirectory
    abstract val outDir: DirectoryProperty

    @get:Input
    abstract val header: Property<String>

    @TaskAction
    fun generate() {
        val out = outDir.get().asFile
        out.mkdirs()
        sourceDir.asFileTree.files.forEach { f ->
            out.resolve(f.name + ".txt").writeText(header.get() + f.readText())
        }
    }
}

tasks.register<GenerateSnippets>("generateSnippets") {
    sourceDir.set(layout.projectDirectory.dir("src/snippets"))
    outDir.set(layout.buildDirectory.dir("generated/snippets"))
    header.set("// generated by generateSnippets")
}

// ./gradlew generateSnippets  ->  executed
// ./gradlew generateSnippets  ->  UP-TO-DATE

// gradle.properties
org.gradle.configuration-cache=true
org.gradle.configuration-cache.problems=warn   // temporary during adoption

// BREAKS the configuration cache: captures a value at configuration time
tasks.register("bad") {
    val stamp = System.currentTimeMillis()
    doLast { println(stamp) }
}

// Configuration-cache-safe: the value is read at execution time
abstract class StampTask : DefaultTask() {
    @get:Input
    abstract val stamp: Property<Long>

    @TaskAction
    fun printStamp() { println(stamp.get()) }
}
tasks.register<StampTask>("good") {
    stamp.set(providers.systemProperty("BUILD_STAMP").map(String::toLong))
}

